# coverage-dc.md DRE rows), one `DCM-dre` card per register row. Each card keeps the row's typed statements and
# constraints as sentences; repeated people are named (their person cards are in the same tab), distinct offices
# and source contexts stay separate. Sources: one official section link per section the row names (verses merged).

from copy_dc import P, S

COPY = {
    'SD0998': ('DCM-dre030-whitmer-cowdery', 'Peter Whitmer Jr. and Oliver Cowdery: companions', P + 'Section 30:5–7 assigns Peter Whitmer Jr. as Oliver Cowdery’s companion, as part of the instruction for the western mission.'),
    'SD0999': ('DCM-dre032-western-mission-party', 'Pratt and Peterson join the western mission', P + 'Section 32:1–3 directs Parley P. Pratt and Ziba Peterson to join Oliver Cowdery and Peter Whitmer Jr. in the mission. One party; it is not split into invented pairs.'),
    'SD1000': ('DCM-dre049-shaker-mission', 'The mission to the Shakers', P + 'The heading and verse 1 of section 49 assign Sidney Rigdon, Parley P. Pratt and Leman Copley jointly to the Shaker mission; the heading describes them carrying the revelation to that community.'),
    'SD1001': ('DCM-dre050-strengthen-churches', 'Wakefield, Pratt and Corrill: strengthening the churches', P + 'Section 50:37–38 assigns Joseph Wakefield and Parley P. Pratt to strengthen the churches, and separately calls John Corrill to the same work. Corrill is not made a third fixed companion.'),
    'SD1002': ('DCM-dre052a-companion-pairs', 'Thirteen companion pairs in section 52', P + 'Section 52 (verses 3, 7–8 and 22–32) names thirteen companion pairs: Joseph Smith Jr. and Sidney Rigdon; Lyman Wight and John Corrill; John Murdock and Hyrum Smith; Thomas B. Marsh and Ezra Thayre; Isaac Morley and Ezra Booth; David Whitmer and Harvey Whitlock; Parley P. Pratt and Orson Pratt; Solomon Hancock and Simeon Carter; Edson Fuller and Jacob Scott; Levi W. Hancock and Zebedee Coltrin; Reynolds Cahoon and Samuel H. Smith; Wheeler Baldwin and William Carter; Newel Knight and Selah J. Griffin. Murdock and Hyrum Smith’s route is given only as by way of Detroit. See “Mission companions in section 52”.'),
    'SD1003': ('DCM-dre052b-partridge-harris', 'Partridge and Harris travel with Smith and Rigdon', P + 'Section 52:24 directs Edward Partridge and Martin Harris to travel with Joseph Smith Jr. and Sidney Rigdon. They join that party; no separate Partridge–Harris pair is inferred.'),
    'SD1004': ('DCM-dre052c-eastern-charges', 'Eastern companions, a reassigned charge and two ordinations', P + 'Section 52:35–38 assigns Joseph Wakefield and Solomon Humphrey as companions to the east, takes the charge given Heman Basset and places it on Simonds Ryder, and directs that Jared Carter and George James be ordained priests. The reassigned charge does not make Basset and Ryder related or the same person.'),
    'SD1005': ('DCM-dre053-gilbert-travels', 'Sidney Gilbert travels with Smith and Rigdon', P + 'Section 53:5 directs Algernon Sidney Gilbert to travel with the Smith and Rigdon party.'),
    'SD1006': ('DCM-dre055-phelps-coe', 'Phelps and Coe travel with Smith and Rigdon', P + 'Section 55:5–6 directs William W. Phelps and Joseph Coe to travel with the Smith and Rigdon party; verse 4 names Phelps to assist Oliver Cowdery with publication.'),
    'SD1007': ('DCM-dre056-revisions', 'Section 56 revises the companions', P + 'Section 56:5–10 pairs Thomas B. Marsh with Selah J. Griffin instead, keeps Newel Knight as leader of the Thompson group, and allows Ezra Thayre to be restored to his former mission on conditions. The section 52 pairings are replaced only from this revelation’s date.'),
    'SD1008': ('DCM-dre058-return-party', 'Smith, Rigdon and Cowdery: the return party', P + 'Sections 58:58, 60:6 and 61:23–35 command Joseph Smith Jr., Sidney Rigdon and Oliver Cowdery to return as a party; each source’s route instructions are kept as given. See “Return from Missouri: distinct routes and duties”.'),
    'SD1009': ('DCM-dre061-cahoon-samuel-smith', 'Cahoon and Samuel H. Smith remain together', P + 'Section 61:35 instructs Reynolds Cahoon and Samuel H. Smith to remain together as companions. It does not establish every road they traveled.'),
    'SD1010': ('DCM-dre066-mclellin-samuel-smith', 'McLellin and Samuel H. Smith: eastern companions', P + 'Section 66:7–8 pairs William E. McLellin and Samuel H. Smith as companions in the east; section 75:6–9 later revokes and revises that pairing.'),
    'SD1011': ('DCM-dre069-cowdery-whitmer', 'Cowdery and John Whitmer: the manuscript journey', P + 'Section 69:1–2 makes Oliver Cowdery and John Whitmer companions for the journey with the manuscript and funds; verses 3–8 separately instruct John Whitmer to gather records.'),
    'SD1012': ('DCM-dre075-companion-pairs', 'Twelve companion pairs in section 75', P + 'Section 75 (verses 6–17 and 30–36) names twelve pairs: William E. McLellin and Luke S. Johnson (south); Orson Hyde and Samuel H. Smith (east); Lyman E. Johnson and Orson Pratt (east); Asa Dodds and Calves Wilson (west); Major N. Ashley and Burr Riggs (south); Simeon Carter and Emer Harris; Ezra Thayre and Thomas B. Marsh; Hyrum Smith and Reynolds Cahoon; Daniel Stanton and Seymour Brunson; Sylvester Smith and Gideon Carter; Ruggles Eames and Stephen Burnett; Micah B. Welton and Eden Smith. No direction is given for the last seven; verses 24–28 set conditions for supporting the families. See “Mission companions in section 75”.'),
    'SD1013': ('DCM-dre078-zion-council-party', 'Smith, Rigdon and Whitney: travel to the council in Zion', P + 'Section 78:9 directs Smith, Rigdon and Whitney to travel as a party to sit in council in Zion. No intermediate stops are inferred.'),
    'SD1014': ('DCM-dre080-burnett-eden-smith', 'Stephen Burnett and Eden Smith: companions', P + 'Section 80:1–3 assigns Stephen Burnett and Eden Smith as companions and leaves the destination to their discretion. For this commission it supersedes their section 75 pairings.'),
    'SD1015': ('DCM-dre090-vienna-jaques', 'Vienna Jaques travels to Zion', P + 'Section 90:28–31 directs that Vienna Jaques go to Zion and that Church leaders provide her financial support. No male companion or household kinship is added.'),
    'SD1016': ('DCM-dre099-murdock-mission', 'John Murdock: an eastern mission and his children', P + 'The heading and verses 1 and 6–8 of section 99 assign John Murdock to an eastern mission and charge him with providing for his dependent children. The children are not named, and the households that cared for them are not identified.'),
    'SD1017': ('DCM-dre103-recruitment-pairs', 'Four recruitment pairs in section 103', P + 'Section 103:37–40 names four recruiting pairs: Joseph Smith Jr. and Parley P. Pratt; Sidney Rigdon and Lyman Wight; Hyrum Smith and Frederick G. Williams; Orson Hyde and Orson Pratt. The numbers of men requested are not actual company rosters.'),
    'SD1018': ('DCM-dre111-salem-party', 'The Salem traveling party', P + 'The heading of section 111 reports Joseph Smith Jr., Sidney Rigdon, Hyrum Smith and Oliver Cowdery traveling as a party; their completed round trip belongs to the heading’s editorial narrative. See “The Salem investigation”.'),
    'SD1019': ('DCM-dre117-marks-whitney-granger', 'Marks, Whitney and Granger: separate instructions', P + 'Section 117 (verses 1 and 10–15) instructs William Marks to move to Far West and preside there, Newel K. Whitney to move to Adam-ondi-Ahman as bishop, and Oliver Granger to work for the Presidency’s financial redemption. No fixed Marks–Whitney pair is inferred.'),
    'SD1020': ('DCM-dre118-marsh-and-twelve', 'Marsh remains; four appointed to the Twelve', P + 'Section 118:2 directs Thomas B. Marsh to remain in Zion for the publication work; verse 6 appoints John Taylor, John E. Page, Wilford Woodruff and Willard Richards to fill vacancies in the Twelve. “Thomas” is resolved to Thomas B. Marsh by the current official footnote 2a, not from the name alone.'),
    'SD1021': ('DCM-dre124a-galland-hyrum-law', 'Galland, Hyrum Smith and Law: separate commissions', P + 'Section 124:79 directs that Isaac Galland be ordained by William Marks and go with Hyrum Smith as his companion; verse 102 reserves a future mission for William Law with Hyrum Smith. Different commissions; no actual departure is added.'),
    'SD1022': ('DCM-dre124b-proclamation-helpers', 'Helpers with the proclamation', P + 'Section 124:12, 16 and 107 direct Robert B. Thompson to help Joseph Smith write the proclamation, John C. Bennett to help with its distribution and labor, and Sidney Rigdon and William Law to assist with it. These are conditional role instructions.'),
    'SD1023': ('DCM-dre124c-nauvoo-house-quorum', 'The Nauvoo House quorum', P + 'Section 124:62–71 names George Miller, Lyman Wight, John Snider and Peter Haws to organize the Nauvoo House quorum as its trustees. The president to be chosen from among them is not named, and none is assumed.'),
    'SD1024': ('DCM-dre124d-nauvoo-house-stock', 'Nauvoo House stock subscriptions', P + 'Section 124:72–82 and 111–117 direct Joseph Smith Jr., Vinson Knight, Hyrum Smith, Isaac Galland, William Marks, Henry G. Sherwood, William Law, Amos Davies and Robert D. Foster to subscribe stock in the Nauvoo House. These are directions, not proof that payment was made. Verse 115 separately directs Robert D. Foster to build a house for Joseph according to their contract.'),
    'SD1025': ('DCM-dre124e-presidency-patriarch', 'The Presidency and the patriarch in section 124', P + 'Section 124:91–97 and 124–126 appoint Hyrum Smith patriarch and seer, name Joseph Smith Jr. presiding elder, translator, revelator, seer and prophet, and name Sidney Rigdon and William Law counselors in the Presidency. William Law takes the counselor role Hyrum held; they are not the same person.'),
    'SD1026': ('DCM-dre124f-twelve', 'The Twelve named in section 124', P + 'Section 124:127–130 names Brigham Young president of the Twelve and Heber C. Kimball, Parley P. Pratt, Orson Pratt, Orson Hyde, William Smith, John Taylor, John E. Page, Wilford Woodruff, Willard Richards and George A. Smith as its members, and notes that David W. Patten has died. Eleven living leaders including Young; no twelfth living name is added.'),
    'SD1027': ('DCM-dre124g-high-council', 'The high council in section 124', P + 'Section 124:131–132 names Samuel Bent, Henry G. Sherwood, George W. Harris, Charles C. Rich, Thomas Grover, Newel Knight, David Dort, Dunbar Wilson, Aaron Johnson, David Fullmer, Alpheus Cutler and William Huntington to the high council for the cornerstone of Zion: twelve living names, with Aaron Johnson in place of the deceased Seymour Brunson. Not merged with the Kirtland high council of section 102.'),
    'SD1028': ('DCM-dre124h-high-priests', 'The high priests quorum presidency', P + 'Section 124:133–136 names Don C. Smith president of the high priests quorum, with Amasa Lyman and Noah Packard as his counselors.'),
    'SD1029': ('DCM-dre124i-elders-quorum', 'The elders quorum presidency', P + 'Section 124:137 names John A. Hicks, Samuel Williams and Jesse Baker as the elders quorum presidency. The verse does not say which is first or second counselor.'),
    'SD1030': ('DCM-dre124j-seventy', 'The presidents of the Seventy', P + 'Section 124:138 names Joseph Young, Josiah Butterfield, Daniel Miles, Henry Herriman, Zera Pulsipher, Levi W. Hancock and James Foster to preside over the Seventy. Seven names; no order of seniority is inferred.'),
    'SD1031': ('DCM-dre124k-bishopric-priests', 'The bishopric and the priests', P + 'Section 124:141–142 names Vinson Knight, Samuel H. Smith and Shadrach Roundy as the bishopric presidency, Roundy “if he will receive it”, and Samuel Rolfe as president of the priests. His counselors and the presidencies of the teachers, deacons and stakes are left unnamed.'),
    'SD1032': ('DCM-dre126-brigham-young-family', 'Brigham Young returns to his family', P + 'The heading and verses 1–3 of section 126 address Brigham Young after his return to his family in Nauvoo and relax his future travel so he can care for them. The heading says the mission in England lasted nearly two years; this does not claim that all his travel ceased.'),
    'SD1033': ('DCM-dre136-company-organizers', 'Three organizer pairs in section 136', P + 'Section 136:12–14 names three pairs to organize companies: Ezra T. Benson and Erastus Snow; Orson Pratt and Wilford Woodruff; Amasa Lyman and George A. Smith. Organizers, not full wagon manifests. See “Organizers of the westward companies”.'),
}

